INSERT INTO `wp_options` VALUES (593,'mxchat_options','a:60:{s:7:\"api_key\";s:0:\"\";s:11:\"xai_api_key\";s:0:\"\";s:14:\"claude_api_key\";s:0:\"\";s:23:\"enable_streaming_toggle\";s:3:\"off\";s:17:\"enable_web_search\";s:3:\"off\";s:16:\"deepseek_api_key\";s:0:\"\";s:14:\"gemini_api_key\";s:0:\"\";s:30:\"enable_woocommerce_integration\";s:3:\"off\";s:26:\"system_prompt_instructions\";s:1448:\"You are an AI Chatbot assistant for this website. Your main goal is to assist visitors with questions and provide helpful information. Here are your key guidelines:\n\n        # Response Style - CRITICALLY IMPORTANT\n        - MAXIMUM LENGTH: 1-3 short sentences per response\n        - Ultra-concise: Get straight to the answer with no filler\n        - No introductions like \"Sure!\" or \"I\'d be happy to help\"\n        - No phrases like \"based on my knowledge\" or \"according to information\"\n        - No explanatory text before giving the answer\n        - No summaries or repetition\n        - Hyperlink all URLs\n        - Respond in user\'s language\n        - Minor chit chat or conversation is okay, but try to keep it focused on [insert topic]\n\n        # Knowledge Base Requirements - PREVENT HALLUCINATIONS\n        - ONLY answer questions using information explicitly provided in OFFICIAL KNOWLEDGE DATABASE CONTENT sections marked with ===== delimiters\n        - If required information is NOT in the knowledge database: \"I don\'t have enough information in my knowledge base to answer that question accurately.\"\n        - NEVER invent or hallucinate URLs, links, product specs, procedures, dates, statistics, names, contacts, or company information\n        - When knowledge base information is unclear or contradictory, acknowledge the limitation rather than guessing\n        - Better to admit insufficient information than provide inaccurate answers\";s:14:\"append_to_body\";s:3:\"off\";s:25:\"post_type_visibility_mode\";s:3:\"all\";s:25:\"post_type_visibility_list\";a:0:{}s:27:\"contextual_awareness_toggle\";s:3:\"off\";s:21:\"citation_links_toggle\";s:2:\"on\";s:27:\"satisfaction_rating_enabled\";s:3:\"off\";s:32:\"satisfaction_rating_idle_seconds\";i:60;s:28:\"satisfaction_rating_question\";s:0:\"\";s:26:\"satisfaction_rating_thanks\";s:0:\"\";s:31:\"satisfaction_rating_placeholder\";s:0:\"\";s:25:\"satisfaction_rating_saved\";s:0:\"\";s:13:\"top_bar_title\";s:6:\"MxChat\";s:13:\"ai_agent_text\";s:8:\"AI Agent\";s:18:\"enable_email_block\";s:0:\"\";s:28:\"email_blocker_header_content\";s:99:\"<h2>Welcome to Our Chat!</h2>\n<p>Let\'s get started. Enter your email to begin chatting with us.</p>\";s:25:\"email_blocker_button_text\";s:10:\"Start Chat\";s:17:\"enable_name_field\";s:3:\"off\";s:22:\"name_field_placeholder\";s:15:\"Enter your name\";s:13:\"intro_message\";s:34:\"Hello! How can I assist you today?\";s:10:\"input_copy\";s:17:\"How can I assist?\";s:18:\"rate_limit_message\";s:44:\"Rate limit exceeded. Please try again later.\";s:16:\"pre_chat_message\";s:27:\"Hey there! Ask me anything!\";s:14:\"voyage_api_key\";s:0:\"\";s:15:\"embedding_model\";s:22:\"text-embedding-ada-002\";s:5:\"model\";s:11:\"gpt-5.6-sol\";s:18:\"link_target_toggle\";s:3:\"off\";s:13:\"loops_api_key\";s:0:\"\";s:18:\"popular_question_1\";s:0:\"\";s:18:\"popular_question_2\";s:0:\"\";s:18:\"popular_question_3\";s:0:\"\";s:18:\"loops_mailing_list\";s:0:\"\";s:25:\"triggered_phrase_response\";s:73:\"Would you like to join our mailing list? Please provide your email below.\";s:22:\"email_capture_response\";s:66:\"Thank you for providing your email! You\'ve been added to our list.\";s:19:\"chat_toolbar_toggle\";s:3:\"off\";s:22:\"show_pdf_upload_button\";s:2:\"on\";s:23:\"show_word_upload_button\";s:2:\"on\";s:23:\"pdf_intent_trigger_text\";s:56:\"Please provide the URL to the PDF you\'d like to discuss.\";s:23:\"pdf_intent_success_text\";s:60:\"I\'ve processed the PDF. What questions do you have about it?\";s:21:\"pdf_intent_error_text\";s:67:\"Sorry, I couldn\'t process the PDF. Please ensure it\'s a valid file.\";s:13:\"pdf_max_pages\";i:69;s:22:\"live_agent_webhook_url\";s:0:\"\";s:21:\"live_agent_secret_key\";s:0:\"\";s:20:\"live_agent_bot_token\";s:0:\"\";s:15:\"telegram_status\";s:3:\"off\";s:18:\"telegram_bot_token\";s:0:\"\";s:17:\"telegram_group_id\";s:0:\"\";s:23:\"telegram_webhook_secret\";s:64:\"nlrR9kpZ817b4aqReCVB8hCbdP5QP0w5g0VaeUhPl7rQtRg4VFkZL2C3mllOmnBG\";s:29:\"telegram_notification_message\";s:146:\"I\'ve notified a support agent. Please allow a moment for them to respond. If you\'d like to continue with AI, just type \"Switch to AI\" at any time.\";s:21:\"telegram_away_message\";s:274:\"I just checked, and it looks like our support team isn\'t personally available at the moment. If you\'d like, you can leave your email address, and they\'ll get back to you as soon as possible. In the meantime, you can keep chatting with me — just let me know how I can help!\";s:23:\"script_loading_strategy\";s:7:\"default\";s:10:\"debug_mode\";s:3:\"off\";}','auto');
