INSERT INTO `wp_posts` VALUES (232,1,'2026-08-16 23:33:48','2026-08-16 21:33:48','<h2>Mathematical Identity</h2>															<img width=\"220\" height=\"300\" src=\"http://your-own-blaiprint.local/wp-content/uploads/2026/08/Immagine_2026-08-16_231918-removebg-preview-220x300.png\" alt=\"\" srcset=\"http://your-own-blaiprint.local/wp-content/uploads/2026/08/Immagine_2026-08-16_231918-removebg-preview-220x300.png 220w, http://your-own-blaiprint.local/wp-content/uploads/2026/08/Immagine_2026-08-16_231918-removebg-preview.png 360w\" sizes=\"(max-width: 220px) 100vw, 220px\" />																		\n								<figure><img src=\"http://your-own-blaiprint.local/wp-content/uploads/2026/08/images-150x150.png\" alt=\"images\" /></figure><figure><img src=\"http://your-own-blaiprint.local/wp-content/uploads/2026/08/Hatsune_miku_v2_render-150x150.png\" alt=\"Hatsune_miku_v2_render\" /></figure><figure><img src=\"http://your-own-blaiprint.local/wp-content/uploads/2026/08/dolphin_render-150x150.png\" alt=\"dolphin_render\" /></figure>			\n				<style>\n/* Contenitore della grafica matematica */\n.math-graphics {\n    display: flex;\n    justify-content: center;\n    align-items: center;\n    gap: 30px;\n    padding: 20px;\n    background: linear-gradient(135deg, #f5f7fa 0%, #c3cfe2 100%);\n    border-radius: 15px;\n    margin: 20px 0;\n    flex-wrap: wrap;\n}\n/* Singolo elemento grafico */\n.math-item {\n    background: rgba(255,255,255,0.9);\n    padding: 20px 30px;\n    border-radius: 12px;\n    box-shadow: 0 4px 15px rgba(0,0,0,0.1);\n    text-align: center;\n    transition: transform 0.3s ease;\n    min-width: 120px;\n}\n.math-item:hover {\n    transform: translateY(-5px);\n}\n/* Simboli matematici decorativi */\n.math-symbol {\n    font-size: 2.5em;\n    color: #2c3e50;\n    font-weight: bold;\n}\n.math-label {\n    font-size: 0.9em;\n    color: #7f8c8d;\n    margin-top: 5px;\n    font-family: \'Courier New\', monospace;\n}\n/* Linee decorative */\n.math-divider {\n    width: 100%;\n    height: 3px;\n    background: linear-gradient(90deg, transparent, #3498db, #2ecc71, #3498db, transparent);\n    margin: 20px 0;\n    border-radius: 2px;\n}\n</style>\n<!-- Esempio di grafica matematica -->\n        ∫\n        Integrale\n        ∑\n        Sommatoria\n        π\n        Pi Greco\n        ∞\n        Infinito','Mathematical Identity','','inherit','closed','closed','','195-revision-v1','','','2026-08-16 23:33:48','2026-08-16 21:33:48','',195,'http://your-own-blaiprint.local/?p=232',0,'revision','',0);
