INSERT INTO `wp_posts` VALUES (266,1,'2026-08-17 15:15:26','2026-08-17 13:15:26','<!-- Global Site Tag (gtag.js) - Google Analytics -->\r\n<script async src=\"https://www.googletagmanager.com/gtag/js?id=GA_TRACKING_ID\"></script>\r\n<script>\r\n	window.dataLayer = window.dataLayer || [];\r\n	function gtag(){dataLayer.push(arguments);}\r\n	gtag(\'js\', new Date());\r\n	gtag(\'config\', \'GA_TRACKING_ID\');\r\n</script>\r\n<!-- End global Site Tag (gtag.js) - Google Analytics -->\r\n','Simple universal snippet: Google analytics tracking','','publish','closed','closed','','simple-universal-snippet-google-analytics-tracking','','','2026-08-17 15:15:26','2026-08-17 13:15:26','',0,'http://your-own-blaiprint.local/?p=266',0,'wbcr-snippets','',0);
INSERT INTO `wp_posts` VALUES (267,1,'2026-08-17 15:15:26','2026-08-17 13:15:26','<h3>What is Lorem Ipsum?</h3>Lorem Ipsum is simply dummy text of the printing and typesetting industry. Lorem Ipsum has been the industry\'s standard dummy text ever since the 1500s, when an unknown printer took a galley of type and scrambled it to make a type specimen book. It has survived not only five centuries, but also the leap into electronic typesetting, remaining essentially unchanged. It was popularised in the 1960s with the release of Letraset sheets containing Lorem Ipsum passages, and more recently with desktop publishing software like Aldus PageMaker including versions of Lorem Ipsum.\r\n{{SNIPPET_CONTENT}}\r\n','Simple text snippet: What is Lorem Ipsum?','','publish','closed','closed','','simple-text-snippet-what-is-lorem-ipsum','','','2026-08-17 15:15:26','2026-08-17 13:15:26','',0,'http://your-own-blaiprint.local/?p=267',0,'wbcr-snippets','',0);
INSERT INTO `wp_posts` VALUES (268,1,'2026-08-17 15:15:26','2026-08-17 13:15:26','/**\r\n* Disable WP 4.2 emoji\r\n*/\r\nfunction ace_remove_emoji() {\r\n	add_filter( \'emoji_svg_url\', \'__return_false\' );\r\n	remove_action( \'admin_print_styles\', \'print_emoji_styles\' );\r\n	remove_action( \'wp_head\', \'print_emoji_detection_script\', 7 );\r\n	remove_action( \'admin_print_scripts\', \'print_emoji_detection_script\' );\r\n	remove_action( \'wp_print_styles\', \'print_emoji_styles\' );\r\n	remove_filter( \'wp_mail\', \'wp_staticize_emoji_for_email\' );\r\n	remove_filter( \'the_content_feed\', \'wp_staticize_emoji\' );\r\n	remove_filter( \'comment_text_rss\', \'wp_staticize_emoji\' );\r\n	// filter to remove TinyMCE emojis\r\n	add_filter( \'tiny_mce_plugins\', \'ace_disable_emoji_tinymce\' );\r\n}\r\nadd_action( \'init\', \'ace_remove_emoji\' );\r\n/**\r\n* Remove tinyMCE emoji\r\n*/\r\nfunction ace_disable_emoji_tinymce( $plugins ) {\r\n	unset( $plugins[\'wpemoji\'] );\r\n	return $plugins;\r\n}\r\n','Simple php snippet: Disable emojis','','publish','closed','closed','','simple-php-snippet-disable-emojis','','','2026-08-17 15:15:26','2026-08-17 13:15:26','',0,'http://your-own-blaiprint.local/?p=268',0,'wbcr-snippets','',0);
INSERT INTO `wp_posts` VALUES (269,1,'2026-08-17 15:15:27','2026-08-17 13:15:27','<script type=\"text/javascript\">\n    var pixel_id = \'\'; // Add you FB pixel ID!\n    !function (f, b, e, v, n, t, s) {\n        if (f.fbq) return; n = f.fbq = function () {\n            n.callMethod ?\n                n.callMethod.apply(n, arguments) : n.queue.push(arguments)\n        }; if (!f._fbq) f._fbq = n;\n        n.push = n; n.loaded = !0; n.version = \'2.0\'; n.queue = []; t = b.createElement(e); t.async = !0;\n        t.src = v; s = b.getElementsByTagName(e)[0]; s.parentNode.insertBefore(t, s)\n    }(window,document, \'script\', \'https://connect.facebook.net/en_US/fbevents.js\');\n    \n    fbq(\'init\', pixel_id);\n    fbq(\'track\', \'PageView\');\n</script>','Add Facebook Pixel to the Order success page','','publish','closed','closed','','add-facebook-pixel-to-the-order-success-page','','','2026-08-17 15:15:27','2026-08-17 13:15:27','',0,'http://your-own-blaiprint.local/?p=269',0,'wbcr-snippets','',0);
