INSERT INTO `wp_posts` VALUES (290,1,'2026-08-17 21:16:30','2026-08-17 19:16:30','// PARTE 1: GESTORE AJAX LATO SERVER (PHP) ---\r\n// Questa funzione riceve il numero di linee e genera l\'immagine\r\nfunction genera_immagine_con_linee() {\r\n    // Recupera il valore inviato dal JavaScript\r\n    $numero_linee = isset($_POST[\'linee\']) ? intval($_POST[\'linee\']) : 10;\r\n    \r\n    // --- QUI INSERISCI LA TUA LOGICA PER GENERARE L\'IMMAGINE ---\r\n    // Usa $numero_linee per creare il disegno con le linee matematiche\r\n    // Per esempio, potresti chiamare una funzione che crea un SVG\r\n    $immagine_generata = \'<svg>...</svg>\'; // Sostituisci con la tua logica\r\n    \r\n    // Restituisci il risultato al JavaScript (in formato JSON)\r\n    wp_send_json_success(array(\r\n        \'immagine\' => $immagine_generata,\r\n        \'linee\' => $numero_linee\r\n    ));\r\n}\r\n\r\n// Nello snippet PHP\r\n$colore = isset($color) ? $color : \'#4A90E2\';\r\n\r\nadd_action(\'wp_ajax_genera_immagine\', \'genera_immagine_con_linee\');\r\nadd_action(\'wp_ajax_nopriv_genera_immagine\', \'genera_immagine_con_linee\'); // Per utenti non loggati\r\n\r\n// --- PARTE 2: INTERFACCIA UTENTE (HTML + PHP) ---\r\n// Questo è il codice che viene mostrato nella pagina\r\necho \'<div id=\"slider-container\" style=\"color: #4A90E2\">\';\r\necho \'  <label for=\"lineeSlider\">Numero di linee: <span id=\"valoreSlider\">10</span></label><br>\';\r\necho \'  <input type=\"range\" id=\"lineeSlider\" min=\"1\" max=\"20\" value=\"10\" step=\"1\">\';\r\necho \'  <button id=\"generaBtn\">Genera Immagine</button>\';\r\necho \'  <div id=\"risultato\">\';\r\necho \'    <p>Immagine generata con 10 linee</p>\';\r\n// Qui puoi mostrare l\'immagine predefinita\r\necho \'  </div>\';\r\necho \'</div>\';\r\n\r\n// --- PARTE 3: JAVASCRIPT PER L\'INTERATTIVITÀ ---\r\n// Questo codice gestisce l\'interazione con l\'utente e le chiamate AJAX\r\n?>\r\n<script>\r\njQuery(document).ready(function($) {\r\n    // Variabili per i riferimenti agli elementi\r\n    const slider = $(\'#lineeSlider\');\r\n    const valoreDisplay = $(\'#valoreSlider\');\r\n    const bottone = $(\'#generaBtn\');\r\n    const risultatoDiv = $(\'#risultato\');\r\n    \r\n    // Aggiorna il numero visualizzato quando lo slider si muove\r\n    slider.on(\'input\', function() {\r\n        valoreDisplay.text($(this).val());\r\n    });\r\n    \r\n    // Gestione del click del bottone\r\n    bottone.on(\'click\', function() {\r\n        const linee = slider.val();\r\n        risultatoDiv.html(\'<p>Generazione in corso...</p>\');\r\n        \r\n        // Chiamata AJAX al server\r\n        $.ajax({\r\n            url: \'<?php echo admin_url(\'admin-ajax.php\'); ?>\',\r\n            type: \'POST\',\r\n            data: {\r\n                action: \'genera_immagine\',\r\n                linee: linee\r\n            },\r\n            success: function(response) {\r\n                if (response.success) {\r\n                    // Aggiorna il risultato con l\'immagine generata\r\n                    risultatoDiv.html(response.data.immagine);\r\n                } else {\r\n                    risultatoDiv.html(\'<p>Errore nella generazione.</p>\');\r\n                }\r\n            },\r\n            error: function() {\r\n                risultatoDiv.html(\'<p>Errore di connessione al server.</p>\');\r\n            }\r\n        });\r\n    });\r\n});\r\n</script>','Range Slider copy','','trash','closed','closed','','range-slider-copy__trashed','','','2026-08-17 21:44:57','2026-08-17 19:44:57','',0,'http://your-own-blaiprint.local/?post_type=wbcr-snippets&#038;p=290',0,'wbcr-snippets','',0);
INSERT INTO `wp_posts` VALUES (291,1,'2026-08-17 21:16:30','2026-08-17 19:16:30','// Recupera il valore dalla shortcode [wbcr_php_snippet id=\"XXX\" lines=\"5\"]\r\n$numero_linee = isset($lines) ? intval($lines) : 10; // Se non specificato, usa 10 come default\r\n\r\n// Questo è dove inserirai la logica per generare l\'immagine con le linee\r\n// Per ora, mostriamo semplicemente il numero scelto\r\necho \'<p>Numero di linee selezionato: <strong>\' . $numero_linee . \'</strong></p>\';\r\n\r\n// --- ESEMPIO DI SLIDER HTML ---\r\n// Nota: questo è un esempio statico. Per essere interattivo,\r\n// avrai bisogno di JavaScript che aggiorni la pagina in tempo reale.\r\necho \'<input type=\"range\" min=\"1\" max=\"20\" value=\"\' . $numero_linee . \'\" step=\"1\" disabled>\';\r\n\r\n// ---- LASCIA UN COMMENTO PER TE ----\r\n// IL VERO CODICE PER IL GENERATORE DI IMMAGINI VA QUI.\r\n// Puoi usare il valore di $numero_linee per generare il disegno.','Range Slider copy','','inherit','closed','closed','','290-revision-v1','','','2026-08-17 21:16:30','2026-08-17 19:16:30','',290,'http://your-own-blaiprint.local/?p=291',0,'revision','',0);
