INSERT INTO `wp_posts` VALUES (316,1,'2026-08-17 21:41:02','2026-08-17 19:41:02','<h2>Mathematical</h2>															<img width=\"220\" height=\"300\" src=\"http://your-own-blaiprint.local/wp-content/uploads/2026/08/Immagine_2026-08-16_231918-removebg-preview-220x300.png\" alt=\"\" srcset=\"http://your-own-blaiprint.local/wp-content/uploads/2026/08/Immagine_2026-08-16_231918-removebg-preview-220x300.png 220w, http://your-own-blaiprint.local/wp-content/uploads/2026/08/Immagine_2026-08-16_231918-removebg-preview.png 360w\" sizes=\"(max-width: 220px) 100vw, 220px\" />																<h2>Identity</h2>							\n								<figure><img src=\"http://your-own-blaiprint.local/wp-content/uploads/2026/08/images-150x150.png\" alt=\"images\" /></figure><figure><img src=\"http://your-own-blaiprint.local/wp-content/uploads/2026/08/Hatsune_miku_v2_render-150x150.png\" alt=\"Hatsune_miku_v2_render\" /></figure><figure><img src=\"http://your-own-blaiprint.local/wp-content/uploads/2026/08/dolphin_render-150x150.png\" alt=\"dolphin_render\" /></figure><figure><img src=\"http://your-own-blaiprint.local/wp-content/uploads/2026/08/images-1-e1786970743975-150x150.png\" alt=\"images (1)\" /></figure><figure><img src=\"http://your-own-blaiprint.local/wp-content/uploads/2026/08/images-2-e1786970806738-150x150.png\" alt=\"images (2)\" /></figure>			\n				[wbcr_php_snippet id=\"311\"]','Mathematical Identity','','inherit','closed','closed','','195-revision-v1','','','2026-08-17 21:41:02','2026-08-17 19:41:02','',195,'http://your-own-blaiprint.local/?p=316',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (317,1,'2026-08-17 21:52:22','2026-08-17 19:52:22','// --- PARTE 1: GESTORE AJAX LATO SERVER (PHP) ---\r\nfunction genera_immagine_con_linee() {\r\n    $numero_linee = isset($_POST[\'linee\']) ? intval($_POST[\'linee\']) : 10;\r\n    \r\n    // Esempio di generazione SVG con linee\r\n    $svg = genera_svg_con_linee($numero_linee);\r\n    \r\n    wp_send_json_success(array(\r\n        \'immagine\' => $svg,\r\n        \'linee\' => $numero_linee\r\n    ));\r\n}\r\nadd_action(\'wp_ajax_genera_immagine\', \'genera_immagine_con_linee\');\r\nadd_action(\'wp_ajax_nopriv_genera_immagine\', \'genera_immagine_con_linee\');\r\n\r\n// Funzione helper per generare l\'SVG\r\nfunction genera_svg_con_linee($numero_linee) {\r\n    $colore = \'#4A90E2\';\r\n    $larghezza = 600;\r\n    $altezza = 300;\r\n    $padding = 30;\r\n    \r\n    $svg = \'<svg width=\"\' . $larghezza . \'\" height=\"\' . $altezza . \'\" xmlns=\"http://www.w3.org/2000/svg\" style=\"width:100%; height:auto; max-width:600px;\">\';\r\n    $svg .= \'<rect width=\"100%\" height=\"100%\" fill=\"#f8f9fa\" rx=\"12\"/>\';\r\n    \r\n    // Genera linee con gradienti e trasparenze\r\n    for ($i = 1; $i <= $numero_linee; $i++) {\r\n        $y = ($i / ($numero_linee + 1)) * ($altezza - 2 * $padding) + $padding;\r\n        $opacita = 0.2 + ($i / $numero_linee) * 0.8;\r\n        $spessore = 1 + ($i / $numero_linee) * 3;\r\n        \r\n        // Linea principale\r\n        $svg .= \'<line x1=\"\' . $padding . \'\" y1=\"\' . $y . \'\" x2=\"\' . ($larghezza - $padding) . \'\" y2=\"\' . $y . \'\" stroke=\"\' . $colore . \'\" stroke-width=\"\' . $spessore . \'\" opacity=\"\' . $opacita . \'\"/>\';\r\n        \r\n        // Numero della linea (solo su alcune linee per non affollare)\r\n        if ($i % 2 == 0 || $i == 1 || $i == $numero_linee) {\r\n            $svg .= \'<text x=\"\' . ($padding + 5) . \'\" y=\"\' . ($y - 5) . \'\" font-size=\"10\" fill=\"#666\" font-family=\"Arial, sans-serif\">\' . $i . \'</text>\';\r\n        }\r\n    }\r\n    \r\n    // Aggiungi legenda\r\n    $svg .= \'<text x=\"\' . ($larghezza - 100) . \'\" y=\"\' . ($altezza - 10) . \'\" font-size=\"12\" fill=\"#4A90E2\" font-family=\"Arial, sans-serif\" font-weight=\"bold\">\' . $numero_linee . \' linee</text>\';\r\n    \r\n    $svg .= \'</svg>\';\r\n    return $svg;\r\n}\r\n\r\n// --- PARTE 2: INTERFACCIA UTENTE (HTML + PHP) ---\r\necho \'<div id=\"slider-container\" class=\"slider-moderno\">\';\r\n\r\n// Header con titolo\r\necho \'  <div class=\"slider-header\">\';\r\necho \'    <div class=\"slider-title\">\';\r\necho \'      <span class=\"slider-icon\">📐</span>\';\r\necho \'      <h3>Righe Limite</h3>\';\r\necho \'    </div>\';\r\necho \'    <div class=\"slider-info\">\';\r\necho \'      <span class=\"slider-count\" id=\"valoreSlider\">10</span>\';\r\necho \'      <span class=\"slider-label\">linee</span>\';\r\necho \'    </div>\';\r\necho \'  </div>\';\r\n\r\n// Corpo dello slider\r\necho \'  <div class=\"slider-body\">\';\r\necho \'    <input type=\"range\" id=\"lineeSlider\" min=\"1\" max=\"20\" value=\"10\" step=\"1\" class=\"slider-input\">\';\r\necho \'    <div class=\"slider-tickmarks\">\';\r\nfor ($i = 1; $i <= 20; $i += 2) {\r\n    echo \'      <span class=\"tickmark\" data-value=\"\' . $i . \'\">\' . $i . \'</span>\';\r\n}\r\necho \'    </div>\';\r\necho \'  </div>\';\r\n\r\n// Pulsante e risultato\r\necho \'  <div class=\"slider-footer\">\';\r\necho \'    <button id=\"generaBtn\" class=\"btn-genera\">\';\r\necho \'      <span class=\"btn-icon\">✨</span> Genera Immagine\';\r\necho \'    </button>\';\r\necho \'  </div>\';\r\n\r\necho \'  <div id=\"risultato\" class=\"slider-risultato\">\';\r\necho \'    <div class=\"risultato-placeholder\">\';\r\necho \'      <div class=\"placeholder-icon\">🎨</div>\';\r\necho \'      <p>Imposta il numero di linee e clicca su \"Genera Immagine\"</p>\';\r\necho \'      <p class=\"placeholder-small\">(minimo 1, massimo 20 linee)</p>\';\r\necho \'    </div>\';\r\necho \'  </div>\';\r\n\r\necho \'</div>\';\r\n\r\n// --- PARTE 3: CSS PER LO STILE MODERNO ---\r\n?>\r\n<style>\r\n/* Contenitore principale */\r\n.slider-moderno {\r\n    max-width: 700px;\r\n    margin: 0 auto;\r\n    padding: 30px;\r\n    background: #ffffff;\r\n    border-radius: 20px;\r\n    box-shadow: 0 10px 40px rgba(0, 0, 0, 0.08);\r\n    font-family: -apple-system, BlinkMacSystemFont, \'Segoe UI\', Roboto, Oxygen, Ubuntu, sans-serif;\r\n}\r\n\r\n/* Header dello slider */\r\n.slider-header {\r\n    display: flex;\r\n    justify-content: space-between;\r\n    align-items: center;\r\n    margin-bottom: 25px;\r\n    padding-bottom: 15px;\r\n    border-bottom: 2px solid #f0f2f5;\r\n}\r\n\r\n.slider-title {\r\n    display: flex;\r\n    align-items: center;\r\n    gap: 12px;\r\n}\r\n\r\n.slider-icon {\r\n    font-size: 24px;\r\n}\r\n\r\n.slider-title h3 {\r\n    font-size: 18px;\r\n    font-weight: 600;\r\n    color: #1a1a2e;\r\n    margin: 0;\r\n}\r\n\r\n.slider-info {\r\n    display: flex;\r\n    align-items: baseline;\r\n    gap: 6px;\r\n    background: #f8f9fa;\r\n    padding: 6px 16px;\r\n    border-radius: 30px;\r\n}\r\n\r\n.slider-count {\r\n    font-size: 24px;\r\n    font-weight: 700;\r\n    color: #4A90E2;\r\n    min-width: 30px;\r\n    text-align: center;\r\n}\r\n\r\n.slider-label {\r\n    font-size: 14px;\r\n    color: #6c757d;\r\n}\r\n\r\n/* Corpo dello slider */\r\n.slider-body {\r\n    margin-bottom: 20px;\r\n}\r\n\r\n/* Input range personalizzato */\r\n.slider-input {\r\n    -webkit-appearance: none;\r\n    appearance: none;\r\n    width: 100%;\r\n    height: 6px;\r\n    border-radius: 3px;\r\n    background: linear-gradient(to right, #4A90E2 0%, #4A90E2 47%, #e0e5ec 47%, #e0e5ec 100%);\r\n    outline: none;\r\n    transition: background 0.2s ease;\r\n    cursor: pointer;\r\n}\r\n\r\n/* Thumb per Chrome/Safari */\r\n.slider-input::-webkit-slider-thumb {\r\n    -webkit-appearance: none;\r\n    appearance: none;\r\n    width: 22px;\r\n    height: 22px;\r\n    border-radius: 50%;\r\n    background: #4A90E2;\r\n    cursor: pointer;\r\n    box-shadow: 0 2px 8px rgba(74, 144, 226, 0.4);\r\n    transition: all 0.2s ease;\r\n    border: 3px solid white;\r\n}\r\n\r\n.slider-input::-webkit-slider-thumb:hover {\r\n    transform: scale(1.15);\r\n    box-shadow: 0 4px 16px rgba(74, 144, 226, 0.5);\r\n}\r\n\r\n/* Thumb per Firefox */\r\n.slider-input::-moz-range-thumb {\r\n    width: 22px;\r\n    height: 22px;\r\n    border-radius: 50%;\r\n    background: #4A90E2;\r\n    cursor: pointer;\r\n    box-shadow: 0 2px 8px rgba(74, 144, 226, 0.4);\r\n    border: 3px solid white;\r\n}\r\n\r\n/* Track per Firefox */\r\n.slider-input::-moz-range-track {\r\n    height: 6px;\r\n    border-radius: 3px;\r\n    background: #e0e5ec;\r\n}\r\n\r\n/* Tickmarks sotto lo slider */\r\n.slider-tickmarks {\r\n    display: flex;\r\n    justify-content: space-between;\r\n    padding: 8px 6px 0;\r\n    margin-top: 4px;\r\n}\r\n\r\n.tickmark {\r\n    font-size: 11px;\r\n    color: #8c9aab;\r\n    font-weight: 500;\r\n    cursor: default;\r\n    transition: color 0.2s ease;\r\n}\r\n\r\n.tickmark:hover {\r\n    color: #4A90E2;\r\n}\r\n\r\n/* Footer con pulsante */\r\n.slider-footer {\r\n    display: flex;\r\n    justify-content: center;\r\n    margin: 20px 0 25px;\r\n}\r\n\r\n.btn-genera {\r\n    display: inline-flex;\r\n    align-items: center;\r\n    gap: 10px;\r\n    padding: 14px 40px;\r\n    background: linear-gradient(135deg, #4A90E2, #357ABD);\r\n    color: white;\r\n    border: none;\r\n    border-radius: 50px;\r\n    font-size: 16px;\r\n    font-weight: 600;\r\n    cursor: pointer;\r\n    transition: all 0.3s ease;\r\n    box-shadow: 0 4px 16px rgba(74, 144, 226, 0.3);\r\n}\r\n\r\n.btn-genera:hover {\r\n    transform: translateY(-2px);\r\n    box-shadow: 0 6px 24px rgba(74, 144, 226, 0.4);\r\n}\r\n\r\n.btn-genera:active {\r\n    transform: translateY(0);\r\n    box-shadow: 0 2px 8px rgba(74, 144, 226, 0.3);\r\n}\r\n\r\n.btn-icon {\r\n    font-size: 18px;\r\n}\r\n\r\n/* Area del risultato */\r\n.slider-risultato {\r\n    background: #f8f9fa;\r\n    border-radius: 16px;\r\n    min-height: 200px;\r\n    display: flex;\r\n    align-items: center;\r\n    justify-content: center;\r\n    transition: all 0.3s ease;\r\n    border: 2px dashed #e0e5ec;\r\n    padding: 20px;\r\n    overflow: hidden;\r\n}\r\n\r\n.slider-risultato.has-content {\r\n    border-style: solid;\r\n    border-color: #4A90E2;\r\n    background: #ffffff;\r\n}\r\n\r\n.risultato-placeholder {\r\n    text-align: center;\r\n    color: #6c757d;\r\n}\r\n\r\n.placeholder-icon {\r\n    font-size: 48px;\r\n    margin-bottom: 12px;\r\n}\r\n\r\n.risultato-placeholder p {\r\n    margin: 6px 0;\r\n    font-size: 15px;\r\n}\r\n\r\n.placeholder-small {\r\n    font-size: 13px !important;\r\n    color: #adb5bd !important;\r\n}\r\n\r\n/* Stato di caricamento */\r\n.slider-risultato.loading {\r\n    position: relative;\r\n}\r\n\r\n.slider-risultato.loading::after {\r\n    content: \'\';\r\n    position: absolute;\r\n    inset: 0;\r\n    background: rgba(255, 255, 255, 0.7);\r\n    display: flex;\r\n    align-items: center;\r\n    justify-content: center;\r\n    font-size: 24px;\r\n    border-radius: 16px;\r\n}\r\n\r\n/* Responsive */\r\n@media (max-width: 600px) {\r\n    .slider-moderno {\r\n        padding: 20px;\r\n    }\r\n    \r\n    .slider-header {\r\n        flex-direction: column;\r\n        align-items: flex-start;\r\n        gap: 12px;\r\n    }\r\n    \r\n    .slider-title h3 {\r\n        font-size: 16px;\r\n    }\r\n    \r\n    .btn-genera {\r\n        width: 100%;\r\n        justify-content: center;\r\n    }\r\n    \r\n    .slider-tickmarks {\r\n        display: none;\r\n    }\r\n}\r\n</style>\r\n\r\n<?php\r\n// --- PARTE 4: JAVASCRIPT PER L\'INTERATTIVITÀ ---\r\n?>\r\n<script>\r\njQuery(document).ready(function($) {\r\n    const slider = $(\'#lineeSlider\');\r\n    const valoreDisplay = $(\'#valoreSlider\');\r\n    const bottone = $(\'#generaBtn\');\r\n    const risultatoDiv = $(\'#risultato\');\r\n    \r\n    // Aggiorna il valore visualizzato in tempo reale\r\n    slider.on(\'input\', function() {\r\n        const val = $(this).val();\r\n        valoreDisplay.text(val);\r\n        \r\n        // Aggiorna il gradiente della barra\r\n        const percent = ((val - 1) / 19) * 100;\r\n        const trackBg = `linear-gradient(to right, #4A90E2 0%, #4A90E2 ${percent}%, #e0e5ec ${percent}%, #e0e5ec 100%)`;\r\n        $(this).css(\'background\', trackBg);\r\n    });\r\n    \r\n    // Gestione click del pulsante\r\n    bottone.on(\'click\', function() {\r\n        const linee = slider.val();\r\n        const btn = $(this);\r\n        \r\n        // Mostra stato di caricamento\r\n        btn.prop(\'disabled\', true);\r\n        btn.html(\'<span class=\"btn-icon\">⏳</span> Generazione in corso...\');\r\n        risultatoDiv.addClass(\'loading\');\r\n        risultatoDiv.html(\'<div style=\"text-align:center; padding: 30px;\"><div style=\"font-size:32px; margin-bottom:12px;\">⏳</div><p>Generazione in corso...</p></div>\');\r\n        \r\n        // Chiamata AJAX\r\n        $.ajax({\r\n            url: \'<?php echo admin_url(\'admin-ajax.php\'); ?>\',\r\n            type: \'POST\',\r\n            data: {\r\n                action: \'genera_immagine\',\r\n                linee: linee\r\n            },\r\n            success: function(response) {\r\n                if (response.success) {\r\n                    risultatoDiv.removeClass(\'loading\');\r\n                    risultatoDiv.addClass(\'has-content\');\r\n                    risultatoDiv.html(response.data.immagine);\r\n                } else {\r\n                    risultatoDiv.removeClass(\'loading\');\r\n                    risultatoDiv.html(\'<div style=\"text-align:center; padding:30px; color:#dc3545;\"><div style=\"font-size:32px;\">❌</div><p>Errore nella generazione dell\\\'immagine.</p></div>\');\r\n                }\r\n            },\r\n            error: function() {\r\n                risultatoDiv.removeClass(\'loading\');\r\n                risultatoDiv.html(\'<div style=\"text-align:center; padding:30px; color:#dc3545;\"><div style=\"font-size:32px;\">⚠️</div><p>Errore di connessione al server.</p></div>\');\r\n            },\r\n            complete: function() {\r\n                btn.prop(\'disabled\', false);\r\n                btn.html(\'<span class=\"btn-icon\">✨</span> Genera Immagine\');\r\n            }\r\n        });\r\n    });\r\n    \r\n    // Trigger iniziale per impostare il gradiente\r\n    slider.trigger(\'input\');\r\n});\r\n</script>','Range Slider','','inherit','closed','closed','','311-revision-v1','','','2026-08-17 21:52:22','2026-08-17 19:52:22','',311,'http://your-own-blaiprint.local/?p=317',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (318,1,'2026-08-17 21:56:42','2026-08-17 19:56:42','// --- PARTE 1: GESTORE AJAX LATO SERVER (PHP) ---\r\nfunction genera_immagine_con_linee() {\r\n    $numero_linee = isset($_POST[\'linee\']) ? intval($_POST[\'linee\']) : 10;\r\n    \r\n    // Esempio di generazione SVG con linee\r\n    $svg = genera_svg_con_linee($numero_linee);\r\n    \r\n    wp_send_json_success(array(\r\n        \'immagine\' => $svg,\r\n        \'linee\' => $numero_linee\r\n    ));\r\n}\r\nadd_action(\'wp_ajax_genera_immagine\', \'genera_immagine_con_linee\');\r\nadd_action(\'wp_ajax_nopriv_genera_immagine\', \'genera_immagine_con_linee\');\r\n\r\n// Funzione helper per generare l\'SVG\r\nfunction genera_svg_con_linee($numero_linee) {\r\n    $colore = \'#4A90E2\';\r\n    $larghezza = 600;\r\n    $altezza = 300;\r\n    $padding = 30;\r\n    \r\n    $svg = \'<svg width=\"\' . $larghezza . \'\" height=\"\' . $altezza . \'\" xmlns=\"http://www.w3.org/2000/svg\" style=\"width:100%; height:auto; max-width:600px;\">\';\r\n    $svg .= \'<rect width=\"100%\" height=\"100%\" fill=\"#f8f9fa\" rx=\"12\"/>\';\r\n    \r\n    // Genera linee con gradienti e trasparenze\r\n    for ($i = 1; $i <= $numero_linee; $i++) {\r\n        $y = ($i / ($numero_linee + 1)) * ($altezza - 2 * $padding) + $padding;\r\n        $opacita = 0.2 + ($i / $numero_linee) * 0.8;\r\n        $spessore = 1 + ($i / $numero_linee) * 3;\r\n        \r\n        // Linea principale\r\n        $svg .= \'<line x1=\"\' . $padding . \'\" y1=\"\' . $y . \'\" x2=\"\' . ($larghezza - $padding) . \'\" y2=\"\' . $y . \'\" stroke=\"\' . $colore . \'\" stroke-width=\"\' . $spessore . \'\" opacity=\"\' . $opacita . \'\"/>\';\r\n        \r\n        // Numero della linea (solo su alcune linee per non affollare)\r\n        if ($i % 2 == 0 || $i == 1 || $i == $numero_linee) {\r\n            $svg .= \'<text x=\"\' . ($padding + 5) . \'\" y=\"\' . ($y - 5) . \'\" font-size=\"10\" fill=\"#666\" font-family=\"Arial, sans-serif\">\' . $i . \'</text>\';\r\n        }\r\n    }\r\n    \r\n    // Aggiungi legenda\r\n    $svg .= \'<text x=\"\' . ($larghezza - 100) . \'\" y=\"\' . ($altezza - 10) . \'\" font-size=\"12\" fill=\"#4A90E2\" font-family=\"Arial, sans-serif\" font-weight=\"bold\">\' . $numero_linee . \' linee</text>\';\r\n    \r\n    $svg .= \'</svg>\';\r\n    return $svg;\r\n}\r\n\r\n// --- PARTE 2: INTERFACCIA UTENTE (HTML + PHP) ---\r\necho \'<div id=\"slider-container\" class=\"slider-moderno\">\';\r\n\r\n// Header con titolo\r\necho \'  <div class=\"slider-header\" justify-content: center>\';\r\necho \'    <div class=\"slider-title\">\';\r\necho \'      <span class=\"slider-icon\">📐</span>\';\r\necho \'      <h3>Righe Limite</h3>\';\r\necho \'    </div>\';\r\necho \'    <div class=\"slider-info\">\';\r\necho \'      <span class=\"slider-count\" id=\"valoreSlider\">10</span>\';\r\necho \'      <span class=\"slider-label\">linee</span>\';\r\necho \'    </div>\';\r\necho \'  </div>\';\r\n\r\n// Corpo dello slider\r\necho \'  <div class=\"slider-body\">\';\r\necho \'    <input type=\"range\" id=\"lineeSlider\" min=\"1\" max=\"20\" value=\"10\" step=\"1\" class=\"slider-input\">\';\r\necho \'    <div class=\"slider-tickmarks\">\';\r\nfor ($i = 1; $i <= 20; $i += 2) {\r\n    echo \'      <span class=\"tickmark\" data-value=\"\' . $i . \'\">\' . $i . \'</span>\';\r\n}\r\necho \'    </div>\';\r\necho \'  </div>\';\r\n\r\n// Pulsante e risultato\r\necho \'  <div class=\"slider-footer\">\';\r\necho \'    <button id=\"generaBtn\" class=\"btn-genera\">\';\r\necho \'      <span class=\"btn-icon\">✨</span> Genera Immagine\';\r\necho \'    </button>\';\r\necho \'  </div>\';\r\n\r\necho \'  <div id=\"risultato\" class=\"slider-risultato\">\';\r\necho \'    <div class=\"risultato-placeholder\">\';\r\necho \'      <div class=\"placeholder-icon\">🎨</div>\';\r\necho \'      <p>Imposta il numero di linee e clicca su \"Genera Immagine\"</p>\';\r\necho \'      <p class=\"placeholder-small\">(minimo 1, massimo 20 linee)</p>\';\r\necho \'    </div>\';\r\necho \'  </div>\';\r\n\r\necho \'</div>\';\r\n\r\n// --- PARTE 3: CSS PER LO STILE MODERNO ---\r\n?>\r\n<style>\r\n/* Contenitore principale */\r\n.slider-moderno {\r\n    max-width: 700px;\r\n    margin: 0 auto;\r\n    padding: 30px;\r\n    background: #ffffff;\r\n    border-radius: 20px;\r\n    box-shadow: 0 10px 40px rgba(0, 0, 0, 0.08);\r\n    font-family: -apple-system, BlinkMacSystemFont, \'Segoe UI\', Roboto, Oxygen, Ubuntu, sans-serif;\r\n}\r\n\r\n/* Header dello slider */\r\n.slider-header {\r\n    display: flex;\r\n    justify-content: space-between;\r\n    align-items: center;\r\n    margin-bottom: 25px;\r\n    padding-bottom: 15px;\r\n    border-bottom: 2px solid #f0f2f5;\r\n}\r\n\r\n.slider-title {\r\n    display: flex;\r\n    align-items: center;\r\n    gap: 12px;\r\n}\r\n\r\n.slider-icon {\r\n    font-size: 24px;\r\n}\r\n\r\n.slider-title h3 {\r\n    font-size: 18px;\r\n    font-weight: 600;\r\n    color: #1a1a2e;\r\n    margin: 0;\r\n}\r\n\r\n.slider-info {\r\n    display: flex;\r\n    align-items: baseline;\r\n    gap: 6px;\r\n    background: #f8f9fa;\r\n    padding: 6px 16px;\r\n    border-radius: 30px;\r\n}\r\n\r\n.slider-count {\r\n    font-size: 24px;\r\n    font-weight: 700;\r\n    color: #4A90E2;\r\n    min-width: 30px;\r\n    text-align: center;\r\n}\r\n\r\n.slider-label {\r\n    font-size: 14px;\r\n    color: #6c757d;\r\n}\r\n\r\n/* Corpo dello slider */\r\n.slider-body {\r\n    margin-bottom: 20px;\r\n}\r\n\r\n/* Input range personalizzato */\r\n.slider-input {\r\n    -webkit-appearance: none;\r\n    appearance: none;\r\n    width: 100%;\r\n    height: 6px;\r\n    border-radius: 3px;\r\n    background: linear-gradient(to right, #4A90E2 0%, #4A90E2 47%, #e0e5ec 47%, #e0e5ec 100%);\r\n    outline: none;\r\n    transition: background 0.2s ease;\r\n    cursor: pointer;\r\n}\r\n\r\n/* Thumb per Chrome/Safari */\r\n.slider-input::-webkit-slider-thumb {\r\n    -webkit-appearance: none;\r\n    appearance: none;\r\n    width: 22px;\r\n    height: 22px;\r\n    border-radius: 50%;\r\n    background: #4A90E2;\r\n    cursor: pointer;\r\n    box-shadow: 0 2px 8px rgba(74, 144, 226, 0.4);\r\n    transition: all 0.2s ease;\r\n    border: 3px solid white;\r\n}\r\n\r\n.slider-input::-webkit-slider-thumb:hover {\r\n    transform: scale(1.15);\r\n    box-shadow: 0 4px 16px rgba(74, 144, 226, 0.5);\r\n}\r\n\r\n/* Thumb per Firefox */\r\n.slider-input::-moz-range-thumb {\r\n    width: 22px;\r\n    height: 22px;\r\n    border-radius: 50%;\r\n    background: #4A90E2;\r\n    cursor: pointer;\r\n    box-shadow: 0 2px 8px rgba(74, 144, 226, 0.4);\r\n    border: 3px solid white;\r\n}\r\n\r\n/* Track per Firefox */\r\n.slider-input::-moz-range-track {\r\n    height: 6px;\r\n    border-radius: 3px;\r\n    background: #e0e5ec;\r\n}\r\n\r\n/* Tickmarks sotto lo slider */\r\n.slider-tickmarks {\r\n    display: flex;\r\n    justify-content: space-between;\r\n    padding: 8px 6px 0;\r\n    margin-top: 4px;\r\n}\r\n\r\n.tickmark {\r\n    font-size: 11px;\r\n    color: #8c9aab;\r\n    font-weight: 500;\r\n    cursor: default;\r\n    transition: color 0.2s ease;\r\n}\r\n\r\n.tickmark:hover {\r\n    color: #4A90E2;\r\n}\r\n\r\n/* Footer con pulsante */\r\n.slider-footer {\r\n    display: flex;\r\n    justify-content: center;\r\n    margin: 20px 0 25px;\r\n}\r\n\r\n.btn-genera {\r\n    display: inline-flex;\r\n    align-items: center;\r\n    gap: 10px;\r\n    padding: 14px 40px;\r\n    background: linear-gradient(135deg, #4A90E2, #357ABD);\r\n    color: white;\r\n    border: none;\r\n    border-radius: 50px;\r\n    font-size: 16px;\r\n    font-weight: 600;\r\n    cursor: pointer;\r\n    transition: all 0.3s ease;\r\n    box-shadow: 0 4px 16px rgba(74, 144, 226, 0.3);\r\n}\r\n\r\n.btn-genera:hover {\r\n    transform: translateY(-2px);\r\n    box-shadow: 0 6px 24px rgba(74, 144, 226, 0.4);\r\n}\r\n\r\n.btn-genera:active {\r\n    transform: translateY(0);\r\n    box-shadow: 0 2px 8px rgba(74, 144, 226, 0.3);\r\n}\r\n\r\n.btn-icon {\r\n    font-size: 18px;\r\n}\r\n\r\n/* Area del risultato */\r\n.slider-risultato {\r\n    background: #f8f9fa;\r\n    border-radius: 16px;\r\n    min-height: 200px;\r\n    display: flex;\r\n    align-items: center;\r\n    justify-content: center;\r\n    transition: all 0.3s ease;\r\n    border: 2px dashed #e0e5ec;\r\n    padding: 20px;\r\n    overflow: hidden;\r\n}\r\n\r\n.slider-risultato.has-content {\r\n    border-style: solid;\r\n    border-color: #4A90E2;\r\n    background: #ffffff;\r\n}\r\n\r\n.risultato-placeholder {\r\n    text-align: center;\r\n    color: #6c757d;\r\n}\r\n\r\n.placeholder-icon {\r\n    font-size: 48px;\r\n    margin-bottom: 12px;\r\n}\r\n\r\n.risultato-placeholder p {\r\n    margin: 6px 0;\r\n    font-size: 15px;\r\n}\r\n\r\n.placeholder-small {\r\n    font-size: 13px !important;\r\n    color: #adb5bd !important;\r\n}\r\n\r\n/* Stato di caricamento */\r\n.slider-risultato.loading {\r\n    position: relative;\r\n}\r\n\r\n.slider-risultato.loading::after {\r\n    content: \'\';\r\n    position: absolute;\r\n    inset: 0;\r\n    background: rgba(255, 255, 255, 0.7);\r\n    display: flex;\r\n    align-items: center;\r\n    justify-content: center;\r\n    font-size: 24px;\r\n    border-radius: 16px;\r\n}\r\n\r\n/* Responsive */\r\n@media (max-width: 600px) {\r\n    .slider-moderno {\r\n        padding: 20px;\r\n    }\r\n    \r\n    .slider-header {\r\n        flex-direction: column;\r\n        align-items: flex-start;\r\n        gap: 12px;\r\n    }\r\n    \r\n    .slider-title h3 {\r\n        font-size: 16px;\r\n    }\r\n    \r\n    .btn-genera {\r\n        width: 100%;\r\n        justify-content: center;\r\n    }\r\n    \r\n    .slider-tickmarks {\r\n        display: none;\r\n    }\r\n}\r\n</style>\r\n\r\n<?php\r\n// --- PARTE 4: JAVASCRIPT PER L\'INTERATTIVITÀ ---\r\n?>\r\n<script>\r\njQuery(document).ready(function($) {\r\n    const slider = $(\'#lineeSlider\');\r\n    const valoreDisplay = $(\'#valoreSlider\');\r\n    const bottone = $(\'#generaBtn\');\r\n    const risultatoDiv = $(\'#risultato\');\r\n    \r\n    // Aggiorna il valore visualizzato in tempo reale\r\n    slider.on(\'input\', function() {\r\n        const val = $(this).val();\r\n        valoreDisplay.text(val);\r\n        \r\n        // Aggiorna il gradiente della barra\r\n        const percent = ((val - 1) / 19) * 100;\r\n        const trackBg = `linear-gradient(to right, #4A90E2 0%, #4A90E2 ${percent}%, #e0e5ec ${percent}%, #e0e5ec 100%)`;\r\n        $(this).css(\'background\', trackBg);\r\n    });\r\n    \r\n    // Gestione click del pulsante\r\n    bottone.on(\'click\', function() {\r\n        const linee = slider.val();\r\n        const btn = $(this);\r\n        \r\n        // Mostra stato di caricamento\r\n        btn.prop(\'disabled\', true);\r\n        btn.html(\'<span class=\"btn-icon\">⏳</span> Generazione in corso...\');\r\n        risultatoDiv.addClass(\'loading\');\r\n        risultatoDiv.html(\'<div style=\"text-align:center; padding: 30px;\"><div style=\"font-size:32px; margin-bottom:12px;\">⏳</div><p>Generazione in corso...</p></div>\');\r\n        \r\n        // Chiamata AJAX\r\n        $.ajax({\r\n            url: \'<?php echo admin_url(\'admin-ajax.php\'); ?>\',\r\n            type: \'POST\',\r\n            data: {\r\n                action: \'genera_immagine\',\r\n                linee: linee\r\n            },\r\n            success: function(response) {\r\n                if (response.success) {\r\n                    risultatoDiv.removeClass(\'loading\');\r\n                    risultatoDiv.addClass(\'has-content\');\r\n                    risultatoDiv.html(response.data.immagine);\r\n                } else {\r\n                    risultatoDiv.removeClass(\'loading\');\r\n                    risultatoDiv.html(\'<div style=\"text-align:center; padding:30px; color:#dc3545;\"><div style=\"font-size:32px;\">❌</div><p>Errore nella generazione dell\\\'immagine.</p></div>\');\r\n                }\r\n            },\r\n            error: function() {\r\n                risultatoDiv.removeClass(\'loading\');\r\n                risultatoDiv.html(\'<div style=\"text-align:center; padding:30px; color:#dc3545;\"><div style=\"font-size:32px;\">⚠️</div><p>Errore di connessione al server.</p></div>\');\r\n            },\r\n            complete: function() {\r\n                btn.prop(\'disabled\', false);\r\n                btn.html(\'<span class=\"btn-icon\">✨</span> Genera Immagine\');\r\n            }\r\n        });\r\n    });\r\n    \r\n    // Trigger iniziale per impostare il gradiente\r\n    slider.trigger(\'input\');\r\n});\r\n</script>','Range Slider','','inherit','closed','closed','','311-revision-v1','','','2026-08-17 21:56:42','2026-08-17 19:56:42','',311,'http://your-own-blaiprint.local/?p=318',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (319,1,'2026-08-17 21:57:15','2026-08-17 19:57:15','// --- PARTE 1: GESTORE AJAX LATO SERVER (PHP) ---\r\nfunction genera_immagine_con_linee() {\r\n    $numero_linee = isset($_POST[\'linee\']) ? intval($_POST[\'linee\']) : 10;\r\n    \r\n    // Esempio di generazione SVG con linee\r\n    $svg = genera_svg_con_linee($numero_linee);\r\n    \r\n    wp_send_json_success(array(\r\n        \'immagine\' => $svg,\r\n        \'linee\' => $numero_linee\r\n    ));\r\n}\r\nadd_action(\'wp_ajax_genera_immagine\', \'genera_immagine_con_linee\');\r\nadd_action(\'wp_ajax_nopriv_genera_immagine\', \'genera_immagine_con_linee\');\r\n\r\n// Funzione helper per generare l\'SVG\r\nfunction genera_svg_con_linee($numero_linee) {\r\n    $colore = \'#4A90E2\';\r\n    $larghezza = 600;\r\n    $altezza = 300;\r\n    $padding = 30;\r\n    \r\n    $svg = \'<svg width=\"\' . $larghezza . \'\" height=\"\' . $altezza . \'\" xmlns=\"http://www.w3.org/2000/svg\" style=\"width:100%; height:auto; max-width:600px;\">\';\r\n    $svg .= \'<rect width=\"100%\" height=\"100%\" fill=\"#f8f9fa\" rx=\"12\"/>\';\r\n    \r\n    // Genera linee con gradienti e trasparenze\r\n    for ($i = 1; $i <= $numero_linee; $i++) {\r\n        $y = ($i / ($numero_linee + 1)) * ($altezza - 2 * $padding) + $padding;\r\n        $opacita = 0.2 + ($i / $numero_linee) * 0.8;\r\n        $spessore = 1 + ($i / $numero_linee) * 3;\r\n        \r\n        // Linea principale\r\n        $svg .= \'<line x1=\"\' . $padding . \'\" y1=\"\' . $y . \'\" x2=\"\' . ($larghezza - $padding) . \'\" y2=\"\' . $y . \'\" stroke=\"\' . $colore . \'\" stroke-width=\"\' . $spessore . \'\" opacity=\"\' . $opacita . \'\"/>\';\r\n        \r\n        // Numero della linea (solo su alcune linee per non affollare)\r\n        if ($i % 2 == 0 || $i == 1 || $i == $numero_linee) {\r\n            $svg .= \'<text x=\"\' . ($padding + 5) . \'\" y=\"\' . ($y - 5) . \'\" font-size=\"10\" fill=\"#666\" font-family=\"Arial, sans-serif\">\' . $i . \'</text>\';\r\n        }\r\n    }\r\n    \r\n    // Aggiungi legenda\r\n    $svg .= \'<text x=\"\' . ($larghezza - 100) . \'\" y=\"\' . ($altezza - 10) . \'\" font-size=\"12\" fill=\"#4A90E2\" font-family=\"Arial, sans-serif\" font-weight=\"bold\">\' . $numero_linee . \' linee</text>\';\r\n    \r\n    $svg .= \'</svg>\';\r\n    return $svg;\r\n}\r\n\r\n// --- PARTE 2: INTERFACCIA UTENTE (HTML + PHP) ---\r\necho \'<div id=\"slider-container\" class=\"slider-moderno\">\';\r\n\r\n// Header con titolo\r\necho \'  <div class=\"slider-header\" justify-content:\"center\">\';\r\necho \'    <div class=\"slider-title\">\';\r\necho \'      <span class=\"slider-icon\">📐</span>\';\r\necho \'      <h3>Righe Limite</h3>\';\r\necho \'    </div>\';\r\necho \'    <div class=\"slider-info\">\';\r\necho \'      <span class=\"slider-count\" id=\"valoreSlider\">10</span>\';\r\necho \'      <span class=\"slider-label\">linee</span>\';\r\necho \'    </div>\';\r\necho \'  </div>\';\r\n\r\n// Corpo dello slider\r\necho \'  <div class=\"slider-body\">\';\r\necho \'    <input type=\"range\" id=\"lineeSlider\" min=\"1\" max=\"20\" value=\"10\" step=\"1\" class=\"slider-input\">\';\r\necho \'    <div class=\"slider-tickmarks\">\';\r\nfor ($i = 1; $i <= 20; $i += 2) {\r\n    echo \'      <span class=\"tickmark\" data-value=\"\' . $i . \'\">\' . $i . \'</span>\';\r\n}\r\necho \'    </div>\';\r\necho \'  </div>\';\r\n\r\n// Pulsante e risultato\r\necho \'  <div class=\"slider-footer\">\';\r\necho \'    <button id=\"generaBtn\" class=\"btn-genera\">\';\r\necho \'      <span class=\"btn-icon\">✨</span> Genera Immagine\';\r\necho \'    </button>\';\r\necho \'  </div>\';\r\n\r\necho \'  <div id=\"risultato\" class=\"slider-risultato\">\';\r\necho \'    <div class=\"risultato-placeholder\">\';\r\necho \'      <div class=\"placeholder-icon\">🎨</div>\';\r\necho \'      <p>Imposta il numero di linee e clicca su \"Genera Immagine\"</p>\';\r\necho \'      <p class=\"placeholder-small\">(minimo 1, massimo 20 linee)</p>\';\r\necho \'    </div>\';\r\necho \'  </div>\';\r\n\r\necho \'</div>\';\r\n\r\n// --- PARTE 3: CSS PER LO STILE MODERNO ---\r\n?>\r\n<style>\r\n/* Contenitore principale */\r\n.slider-moderno {\r\n    max-width: 700px;\r\n    margin: 0 auto;\r\n    padding: 30px;\r\n    background: #ffffff;\r\n    border-radius: 20px;\r\n    box-shadow: 0 10px 40px rgba(0, 0, 0, 0.08);\r\n    font-family: -apple-system, BlinkMacSystemFont, \'Segoe UI\', Roboto, Oxygen, Ubuntu, sans-serif;\r\n}\r\n\r\n/* Header dello slider */\r\n.slider-header {\r\n    display: flex;\r\n    justify-content: space-between;\r\n    align-items: center;\r\n    margin-bottom: 25px;\r\n    padding-bottom: 15px;\r\n    border-bottom: 2px solid #f0f2f5;\r\n}\r\n\r\n.slider-title {\r\n    display: flex;\r\n    align-items: center;\r\n    gap: 12px;\r\n}\r\n\r\n.slider-icon {\r\n    font-size: 24px;\r\n}\r\n\r\n.slider-title h3 {\r\n    font-size: 18px;\r\n    font-weight: 600;\r\n    color: #1a1a2e;\r\n    margin: 0;\r\n}\r\n\r\n.slider-info {\r\n    display: flex;\r\n    align-items: baseline;\r\n    gap: 6px;\r\n    background: #f8f9fa;\r\n    padding: 6px 16px;\r\n    border-radius: 30px;\r\n}\r\n\r\n.slider-count {\r\n    font-size: 24px;\r\n    font-weight: 700;\r\n    color: #4A90E2;\r\n    min-width: 30px;\r\n    text-align: center;\r\n}\r\n\r\n.slider-label {\r\n    font-size: 14px;\r\n    color: #6c757d;\r\n}\r\n\r\n/* Corpo dello slider */\r\n.slider-body {\r\n    margin-bottom: 20px;\r\n}\r\n\r\n/* Input range personalizzato */\r\n.slider-input {\r\n    -webkit-appearance: none;\r\n    appearance: none;\r\n    width: 100%;\r\n    height: 6px;\r\n    border-radius: 3px;\r\n    background: linear-gradient(to right, #4A90E2 0%, #4A90E2 47%, #e0e5ec 47%, #e0e5ec 100%);\r\n    outline: none;\r\n    transition: background 0.2s ease;\r\n    cursor: pointer;\r\n}\r\n\r\n/* Thumb per Chrome/Safari */\r\n.slider-input::-webkit-slider-thumb {\r\n    -webkit-appearance: none;\r\n    appearance: none;\r\n    width: 22px;\r\n    height: 22px;\r\n    border-radius: 50%;\r\n    background: #4A90E2;\r\n    cursor: pointer;\r\n    box-shadow: 0 2px 8px rgba(74, 144, 226, 0.4);\r\n    transition: all 0.2s ease;\r\n    border: 3px solid white;\r\n}\r\n\r\n.slider-input::-webkit-slider-thumb:hover {\r\n    transform: scale(1.15);\r\n    box-shadow: 0 4px 16px rgba(74, 144, 226, 0.5);\r\n}\r\n\r\n/* Thumb per Firefox */\r\n.slider-input::-moz-range-thumb {\r\n    width: 22px;\r\n    height: 22px;\r\n    border-radius: 50%;\r\n    background: #4A90E2;\r\n    cursor: pointer;\r\n    box-shadow: 0 2px 8px rgba(74, 144, 226, 0.4);\r\n    border: 3px solid white;\r\n}\r\n\r\n/* Track per Firefox */\r\n.slider-input::-moz-range-track {\r\n    height: 6px;\r\n    border-radius: 3px;\r\n    background: #e0e5ec;\r\n}\r\n\r\n/* Tickmarks sotto lo slider */\r\n.slider-tickmarks {\r\n    display: flex;\r\n    justify-content: space-between;\r\n    padding: 8px 6px 0;\r\n    margin-top: 4px;\r\n}\r\n\r\n.tickmark {\r\n    font-size: 11px;\r\n    color: #8c9aab;\r\n    font-weight: 500;\r\n    cursor: default;\r\n    transition: color 0.2s ease;\r\n}\r\n\r\n.tickmark:hover {\r\n    color: #4A90E2;\r\n}\r\n\r\n/* Footer con pulsante */\r\n.slider-footer {\r\n    display: flex;\r\n    justify-content: center;\r\n    margin: 20px 0 25px;\r\n}\r\n\r\n.btn-genera {\r\n    display: inline-flex;\r\n    align-items: center;\r\n    gap: 10px;\r\n    padding: 14px 40px;\r\n    background: linear-gradient(135deg, #4A90E2, #357ABD);\r\n    color: white;\r\n    border: none;\r\n    border-radius: 50px;\r\n    font-size: 16px;\r\n    font-weight: 600;\r\n    cursor: pointer;\r\n    transition: all 0.3s ease;\r\n    box-shadow: 0 4px 16px rgba(74, 144, 226, 0.3);\r\n}\r\n\r\n.btn-genera:hover {\r\n    transform: translateY(-2px);\r\n    box-shadow: 0 6px 24px rgba(74, 144, 226, 0.4);\r\n}\r\n\r\n.btn-genera:active {\r\n    transform: translateY(0);\r\n    box-shadow: 0 2px 8px rgba(74, 144, 226, 0.3);\r\n}\r\n\r\n.btn-icon {\r\n    font-size: 18px;\r\n}\r\n\r\n/* Area del risultato */\r\n.slider-risultato {\r\n    background: #f8f9fa;\r\n    border-radius: 16px;\r\n    min-height: 200px;\r\n    display: flex;\r\n    align-items: center;\r\n    justify-content: center;\r\n    transition: all 0.3s ease;\r\n    border: 2px dashed #e0e5ec;\r\n    padding: 20px;\r\n    overflow: hidden;\r\n}\r\n\r\n.slider-risultato.has-content {\r\n    border-style: solid;\r\n    border-color: #4A90E2;\r\n    background: #ffffff;\r\n}\r\n\r\n.risultato-placeholder {\r\n    text-align: center;\r\n    color: #6c757d;\r\n}\r\n\r\n.placeholder-icon {\r\n    font-size: 48px;\r\n    margin-bottom: 12px;\r\n}\r\n\r\n.risultato-placeholder p {\r\n    margin: 6px 0;\r\n    font-size: 15px;\r\n}\r\n\r\n.placeholder-small {\r\n    font-size: 13px !important;\r\n    color: #adb5bd !important;\r\n}\r\n\r\n/* Stato di caricamento */\r\n.slider-risultato.loading {\r\n    position: relative;\r\n}\r\n\r\n.slider-risultato.loading::after {\r\n    content: \'\';\r\n    position: absolute;\r\n    inset: 0;\r\n    background: rgba(255, 255, 255, 0.7);\r\n    display: flex;\r\n    align-items: center;\r\n    justify-content: center;\r\n    font-size: 24px;\r\n    border-radius: 16px;\r\n}\r\n\r\n/* Responsive */\r\n@media (max-width: 600px) {\r\n    .slider-moderno {\r\n        padding: 20px;\r\n    }\r\n    \r\n    .slider-header {\r\n        flex-direction: column;\r\n        align-items: flex-start;\r\n        gap: 12px;\r\n    }\r\n    \r\n    .slider-title h3 {\r\n        font-size: 16px;\r\n    }\r\n    \r\n    .btn-genera {\r\n        width: 100%;\r\n        justify-content: center;\r\n    }\r\n    \r\n    .slider-tickmarks {\r\n        display: none;\r\n    }\r\n}\r\n</style>\r\n\r\n<?php\r\n// --- PARTE 4: JAVASCRIPT PER L\'INTERATTIVITÀ ---\r\n?>\r\n<script>\r\njQuery(document).ready(function($) {\r\n    const slider = $(\'#lineeSlider\');\r\n    const valoreDisplay = $(\'#valoreSlider\');\r\n    const bottone = $(\'#generaBtn\');\r\n    const risultatoDiv = $(\'#risultato\');\r\n    \r\n    // Aggiorna il valore visualizzato in tempo reale\r\n    slider.on(\'input\', function() {\r\n        const val = $(this).val();\r\n        valoreDisplay.text(val);\r\n        \r\n        // Aggiorna il gradiente della barra\r\n        const percent = ((val - 1) / 19) * 100;\r\n        const trackBg = `linear-gradient(to right, #4A90E2 0%, #4A90E2 ${percent}%, #e0e5ec ${percent}%, #e0e5ec 100%)`;\r\n        $(this).css(\'background\', trackBg);\r\n    });\r\n    \r\n    // Gestione click del pulsante\r\n    bottone.on(\'click\', function() {\r\n        const linee = slider.val();\r\n        const btn = $(this);\r\n        \r\n        // Mostra stato di caricamento\r\n        btn.prop(\'disabled\', true);\r\n        btn.html(\'<span class=\"btn-icon\">⏳</span> Generazione in corso...\');\r\n        risultatoDiv.addClass(\'loading\');\r\n        risultatoDiv.html(\'<div style=\"text-align:center; padding: 30px;\"><div style=\"font-size:32px; margin-bottom:12px;\">⏳</div><p>Generazione in corso...</p></div>\');\r\n        \r\n        // Chiamata AJAX\r\n        $.ajax({\r\n            url: \'<?php echo admin_url(\'admin-ajax.php\'); ?>\',\r\n            type: \'POST\',\r\n            data: {\r\n                action: \'genera_immagine\',\r\n                linee: linee\r\n            },\r\n            success: function(response) {\r\n                if (response.success) {\r\n                    risultatoDiv.removeClass(\'loading\');\r\n                    risultatoDiv.addClass(\'has-content\');\r\n                    risultatoDiv.html(response.data.immagine);\r\n                } else {\r\n                    risultatoDiv.removeClass(\'loading\');\r\n                    risultatoDiv.html(\'<div style=\"text-align:center; padding:30px; color:#dc3545;\"><div style=\"font-size:32px;\">❌</div><p>Errore nella generazione dell\\\'immagine.</p></div>\');\r\n                }\r\n            },\r\n            error: function() {\r\n                risultatoDiv.removeClass(\'loading\');\r\n                risultatoDiv.html(\'<div style=\"text-align:center; padding:30px; color:#dc3545;\"><div style=\"font-size:32px;\">⚠️</div><p>Errore di connessione al server.</p></div>\');\r\n            },\r\n            complete: function() {\r\n                btn.prop(\'disabled\', false);\r\n                btn.html(\'<span class=\"btn-icon\">✨</span> Genera Immagine\');\r\n            }\r\n        });\r\n    });\r\n    \r\n    // Trigger iniziale per impostare il gradiente\r\n    slider.trigger(\'input\');\r\n});\r\n</script>','Range Slider','','inherit','closed','closed','','311-revision-v1','','','2026-08-17 21:57:15','2026-08-17 19:57:15','',311,'http://your-own-blaiprint.local/?p=319',0,'revision','',0);
