INSERT INTO `wp_posts` VALUES (421,1,'2026-08-20 23:53:41','2026-08-20 21:53:41','// Ricevi i parametri dalla pagina (es. dallo slider e dal modulo di upload)\r\n$immagine_url = $_POST[\'image_url\']; // URL dell\'immagine caricata dall\'utente\r\n$num_linee = $_POST[\'linee\']; // Valore dello slider (es. 15)\r\n\r\n// Definisci una cartella per i file di output\r\n$output_dir = wp_upload_dir()[\'basedir\'] . \'/vectomancy-output/\';\r\nif (!file_exists($output_dir)) {\r\n    mkdir($output_dir, 0755, true);\r\n}\r\n$output_file = $output_dir . \'output_\' . uniqid() . \'.html\'; // Genera un nome univoco\r\n\r\n// Costruisci il comando per Vectomancy\r\n// Con il binario precompilato:\r\n$command = \'/percorso/completo/vectomancy image \' . escapeshellarg($immagine_url) .\r\n           \' --output \' . escapeshellarg($output_file) .\r\n           \' --format html\' . // Genera una pagina HTML con Canvas\r\n           \' --mode spline\' . // \'fourier\' per un tratto unico\r\n           \' --terms \' . intval($num_linee) .\r\n           \' --color true\'; // Mantiene i colori\r\n\r\n// Se usi Docker, il comando sarà simile a:\r\n// $command = \'docker run --rm -v \' . $percorso_della_tua_cartella . \':/data vectomancy run --output /data/output.html /data/input.jpg --format html --terms \' . $num_linee;\r\n\r\n// Esegui il comando e cattura l\'output\r\n$output = shell_exec($command . \' 2>&1\'); // 2>&1 reindirizza gli errori per debug\r\n\r\n// Se il file è stato generato, leggine il contenuto e mostralo nella pagina\r\nif (file_exists($output_file)) {\r\n    $contenuto = file_get_contents($output_file);\r\n    echo \'<div id=\"risultato-immagine\">\';\r\n    echo $contenuto; // Visualizza il risultato\r\n    echo \'</div>\';\r\n} else {\r\n    echo \'<p>Errore nella generazione dell\\\'immagine.</p>\';\r\n}\r\n?>','Vectomancy script','','publish','closed','closed','','vectomancy-script','','','2026-08-20 23:54:20','2026-08-20 21:54:20','',0,'http://your-own-blaiprint.local/mathematical/?post_type=wbcr-snippets&#038;p=421',0,'wbcr-snippets','',0);
